// Authored example: add two data-validation rules to a worksheet, then remove one by its range reference.
package main

import (
	"fmt"
	"log"

	cells_foss "github.com/aspose-cells-foss/Aspose.Cells-FOSS-for-Go/v26/aspose/cells_foss"
)

func main() {
	wb := cells_foss.NewWorkbook()
	ws := wb.Worksheets[0]

	ws.Cells().Set("A1", "Status")
	statusRule := &cells_foss.DataValidation{
		Type:             cells_foss.DataValidationTypeList,
		Formula1:         `"Open,Closed,Pending"`,
		ShowErrorMessage: true,
		ErrorStyle:       cells_foss.ErrorStyleStop,
	}
	if err := ws.AddDataValidation("A2:A20", statusRule); err != nil {
		log.Fatalf("add status rule: %v", err)
	}

	ws.Cells().Set("B1", "Score")
	scoreRule := &cells_foss.DataValidation{
		Type:             cells_foss.DataValidationTypeWhole,
		Formula1:         "0",
		Formula2:         "10",
		ShowErrorMessage: true,
		ErrorStyle:       cells_foss.ErrorStyleWarning,
	}
	if err := ws.AddDataValidation("B2:B20", scoreRule); err != nil {
		log.Fatalf("add score rule: %v", err)
	}

	before := len(ws.DataValidations)

	if err := ws.RemoveDataValidation("A2:A20"); err != nil {
		log.Fatalf("remove status rule: %v", err)
	}
	after := len(ws.DataValidations)

	repeatErr := ws.RemoveDataValidation("A2:A20")

	fmt.Printf("before=%d after=%d remaining-type=%q remove-again-error=%v\n",
		before, after, ws.DataValidations[0].Type, repeatErr != nil)

	if before != 2 {
		log.Fatalf("expected 2 rules before removal, got %d", before)
	}
	if after != 1 {
		log.Fatalf("expected 1 rule after removal, got %d", after)
	}
	if ws.DataValidations[0].Type != cells_foss.DataValidationTypeWhole {
		log.Fatalf("expected the remaining rule to be %q, got %q", cells_foss.DataValidationTypeWhole, ws.DataValidations[0].Type)
	}
	if repeatErr == nil {
		log.Fatalf("expected removing an already-removed ref to fail")
	}
}
