Example:
// Authored example: convert a worksheet to an in-memory CSV grid with ToCSV, then rebuild another worksheet from it with FromCSV.
package main

import (
	"fmt"
	"log"

	cells_foss "github.com/aspose-cells-foss/Aspose.Cells-FOSS-for-Go/v26/aspose/cells_foss"
)

func main() {
	source := cells_foss.NewWorkbook()
	sourceWs := source.Worksheets[0]

	rows := [][]string{
		{"Name", "Department"},
		{"Ada Lovelace", "Engineering"},
		{"Grace Hopper", "Research"},
	}
	for r, row := range rows {
		for c, val := range row {
			ref := string(rune('A'+c)) + fmt.Sprint(r+1)
			if err := sourceWs.Cells().Set(ref, val); err != nil {
				log.Fatalf("set %s: %v", ref, err)
			}
		}
	}

	grid, err := sourceWs.ToCSV(',')
	if err != nil {
		log.Fatalf("to csv: %v", err)
	}

	destination := cells_foss.NewWorkbook()
	destinationWs := destination.Worksheets[0]
	if err := destinationWs.FromCSV(grid, ','); err != nil {
		log.Fatalf("from csv: %v", err)
	}

	cell, err := destinationWs.Cells().Get("B2")
	if err != nil {
		log.Fatalf("get B2: %v", err)
	}

	fmt.Printf("rows=%d cols=%d B2=%q\n", len(grid), len(grid[0]), cell.Value)

	if len(grid) != 3 {
		log.Fatalf("expected 3 rows from ToCSV, got %d", len(grid))
	}
	if cell.Value != "Engineering" {
		log.Fatalf("expected B2 %q, got %q", "Engineering", cell.Value)
	}
}
