	"fmt"
	"log"
	"os"
	"path/filepath"

	cells_foss "github.com/aspose-cells-foss/Aspose.Cells-FOSS-for-Go/v26/aspose/cells_foss"
)

func main() {
	wb := cells_foss.NewWorkbook()
	ws := wb.Worksheets[0]
	if err := ws.Cells().Set("A1", "Total"); err != nil {
		log.Fatalf("set cell: %v", err)
	}
	cell, err := ws.Cells().Get("A1")
	if err != nil {
		log.Fatalf("get cell: %v", err)
	}

	style := cells_foss.NewStyle()
	style.Font.Bold = true
	style.Font.Color = "FFFF0000"
	style.Fill = &cells_foss.Fill{Type: cells_foss.FillTypeSolid, Color: "FFFFFF00"}
	style.Border = &cells_foss.Border{Top: true, Bottom: true}

	if err := cell.SetStyle(style); err != nil {
		log.Fatalf("set style: %v", err)
	}

	outPath := filepath.Join(os.TempDir(), "authored_style_roundtrip_example.xlsx")
	if err := wb.Save(outPath); err != nil {
		log.Fatalf("save: %v", err)
	}
	defer os.Remove(outPath)

	loaded, err := cells_foss.Load(outPath)
	if err != nil {
		log.Fatalf("load: %v", err)
	}

	reloadedCell, err := loaded.Worksheets[0].Cells().Get("A1")
	if err != nil {
		log.Fatalf("get reloaded cell: %v", err)
	}
	reloadedStyle := reloadedCell.GetStyle()
	if reloadedStyle == nil {
		log.Fatalf("expected GetStyle to resolve a style after reload")
	}

	fmt.Printf("bold=%v color=%q fill=%q top-border=%v\n",
		reloadedStyle.Font.Bold, reloadedStyle.Font.Color, reloadedStyle.Fill.Color, reloadedStyle.Border.Top)

	if !reloadedStyle.Font.Bold {
		log.Fatalf("expected the reloaded font to be bold")
	}
	if reloadedStyle.Font.Color != "FFFF0000" {
		log.Fatalf("expected font color %q, got %q", "FFFF0000", reloadedStyle.Font.Color)
	}
	if reloadedStyle.Fill == nil || reloadedStyle.Fill.Color != "FFFFFF00" {
		log.Fatalf("expected fill color %q, got %+v", "FFFFFF00", reloadedStyle.Fill)
	}
	if reloadedStyle.Border == nil || !reloadedStyle.Border.Top {
		log.Fatalf("expected the reloaded border to keep its top edge, got %+v", reloadedStyle.Border)
	}
}
