Adds a structured Table with Worksheet.AddTable, saves and reloads the workbook, then finds the same table again by name with Worksheet.GetTable and checks its Range and HasHeaderRow survived the round trip, and that looking up a name that does not exist returns nil.

Example:
// Authored example: build a structured table, save and reload the workbook, then look it up again with GetTable.
package main

import (
	"fmt"
	"log"
	"os"
	"path/filepath"

	cells_foss "github.com/aspose-cells-foss/Aspose.Cells-FOSS-for-Go/v26/aspose/cells_foss"
)

func main() {
	wb := cells_foss.NewWorkbook()
	ws := wb.Worksheets[0]

	headers := []string{"Product", "Units", "Revenue"}
	for i, h := range headers {
		ref := string(rune('A'+i)) + "1"
		if err := ws.Cells().Set(ref, h); err != nil {
			log.Fatalf("set header: %v", err)
		}
	}
	ws.Cells().Set("A2", "Widget")
	ws.Cells().Set("B2", 10)
	ws.Cells().Set("A3", "Gizmo")
	ws.Cells().Set("B3", 7)

	var tbl *cells_foss.Table = ws.AddTable("A1:C3")
	tbl.HasHeaderRow = true
	tbl.StyleName = "TableStyleMedium2"

	outPath := filepath.Join(os.TempDir(), "authored_table_lookup_example.xlsx")
	if err := wb.Save(outPath); err != nil {
		log.Fatalf("save: %v", err)
	}
	defer os.Remove(outPath)

	loaded, err := cells_foss.Load(outPath)
	if err != nil {
		log.Fatalf("load: %v", err)
	}
	loadedWs := loaded.Worksheets[0]

	found := loadedWs.GetTable(tbl.Name)
	if found == nil {
		log.Fatalf("expected GetTable to find %q after reload", tbl.Name)
	}
	missing := loadedWs.GetTable("NotATable")

	fmt.Printf("table=%q range=%q header=%v style-non-empty=%v missing-lookup-nil=%v\n",
		found.Name, found.Range, found.HasHeaderRow, found.StyleName != "", missing == nil)

	if found.Range != "A1:C3" {
		log.Fatalf("expected range %q, got %q", "A1:C3", found.Range)
	}
	if !found.HasHeaderRow {
		log.Fatalf("expected HasHeaderRow true after reload")
	}
	if found.StyleName == "" {
		log.Fatalf("expected a non-empty StyleName after reload")
	}
	if missing != nil {
		log.Fatalf("expected GetTable to return nil for a missing table name")
	}
}
